{
  "name": "StockVision 2X Dashboard",
  "description": "A high-potential stock monitoring dashboard identifying assets with 2x or more analyst price targets, including technical and financial indicators.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

export interface Stock {
  symbol: string;
  name: string;
  price: string;
  targetPrice: string;
  upside: string;
  peRatio: string;
  marketCap: string;
  rsi: string;
  movingAverage: string;
  description: string;
  analystSentiment: 'Bullish' | 'Neutral' | 'Bearish';
  isSaved?: boolean;
  sourceUrls?: { title: string; uri: string }[];
}

export enum AppTab {
  DASHBOARD = 'DASHBOARD',
  SAVED = 'SAVED'
}

import { GoogleGenAI, Type } from "@google/genai";
import { Stock } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const fetchHighGrowthStocks = async (): Promise<Stock[]> => {
  const prompt = `Find a list of at least 8 real, currently traded stocks (US markets like NASDAQ/NYSE) where the average analyst price target for 2024-2025 suggests a potential gain of 100% (2x) or more from current levels. 
  For each stock, provide the following details in a structured format:
  - Ticker Symbol
  - Company Name
  - Current Price (estimated/recent)
  - Analyst Target Price
  - Calculated Upside (%)
  - P/E Ratio
  - Market Cap
  - Technical Indicator: RSI (approximate recent value)
  - Technical Indicator: 50-day Moving Average status (above/below)
  - Short description of the catalyst for the 2x prediction.
  - Overall Analyst Sentiment.
  Ensure all data is as up-to-date as possible.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              symbol: { type: Type.STRING },
              name: { type: Type.STRING },
              price: { type: Type.STRING },
              targetPrice: { type: Type.STRING },
              upside: { type: Type.STRING },
              peRatio: { type: Type.STRING },
              marketCap: { type: Type.STRING },
              rsi: { type: Type.STRING },
              movingAverage: { type: Type.STRING },
              description: { type: Type.STRING },
              analystSentiment: { type: Type.STRING },
            },
            required: ["symbol", "name", "price", "targetPrice", "upside"]
          }
        }
      },
    });

    const resultText = response.text;
    const stocks: Stock[] = JSON.parse(resultText);

    // Enrich with grounding links if available
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sourceUrls = chunks
      .filter(c => c.web)
      .map(c => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '' }));

    return stocks.map(stock => ({
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    }));
  } catch (error) {
    console.error("Error fetching stocks:", error);
    throw error;
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { fetchHighGrowthStocks } from './services/geminiService';
import { Stock, AppTab } from './types';
import { StockCard } from './components/StockCard';

const App: React.FC = () => {
  const [stocks, setStocks] = useState<Stock[]>([]);
  const [savedSymbols, setSavedSymbols] = useState<string[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.DASHBOARD);
  const [lastRefreshed, setLastRefreshed] = useState<Date>(new Date());

  const loadData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchHighGrowthStocks();
      setStocks(data);
      setLastRefreshed(new Date());
    } catch (err) {
      setError('לא הצלחנו לטעון את נתוני המניות. אנא נסו שוב מאוחר יותר.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    // Load saved stocks from localStorage
    const saved = localStorage.getItem('saved_stocks');
    if (saved) {
      setSavedSymbols(JSON.parse(saved));
    }
    loadData();
  }, [loadData]);

  const toggleSave = (symbol: string) => {
    const newSaved = savedSymbols.includes(symbol)
      ? savedSymbols.filter(s => s !== symbol)
      : [...savedSymbols, symbol];

    setSavedSymbols(newSaved);
    localStorage.setItem('saved_stocks', JSON.stringify(newSaved));
  };

  const filteredStocks = activeTab === AppTab.DASHBOARD 
    ? stocks 
    : stocks.filter(s => savedSymbols.includes(s.symbol));

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 pb-20">
      {/* Header */}
      <header className="sticky top-0 z-50 bg-slate-900/80 backdrop-blur-md border-b border-slate-800 px-4 py-4 sm:px-8">
        <div className="max-w-7xl mx-auto flex flex-col sm:flex-row justify-between items-center gap-4">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg shadow-lg shadow-blue-900/20">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
              </svg>
            </div>
            <div>
              <h1 className="text-2xl font-black bg-gradient-to-r from-blue-400 to-emerald-400 bg-clip-text text-transparent">StockVision 2X</h1>
              <p className="text-xs text-slate-500 font-medium">דשבורד מניות עם פוטנציאל צמיחה של 100%+</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <button 
              onClick={loadData}
              disabled={loading}
              className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-sm font-bold rounded-lg transition-all border border-slate-700 disabled:opacity-50"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
              </svg>
              {loading ? 'מעדכן...' : 'רענן נתונים'}
            </button>
            <div className="text-[10px] text-slate-500 hidden sm:block">
              עדכון אחרון: {lastRefreshed.toLocaleTimeString('he-IL')}
            </div>
          </div>
        </div>
      </header>

      {/* Tabs */}
      <div className="max-w-7xl mx-auto px-4 sm:px-8 mt-8">
        <div className="flex gap-2 p-1 bg-slate-900 rounded-xl border border-slate-800 w-full sm:w-fit">
          <button 
            onClick={() => setActiveTab(AppTab.DASHBOARD)}
            className={`flex-1 sm:flex-none px-6 py-2 rounded-lg font-bold text-sm transition-all ${activeTab === AppTab.DASHBOARD ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
          >
            כל המניות
          </button>
          <button 
            onClick={() => setActiveTab(AppTab.SAVED)}
            className={`flex-1 sm:flex-none px-6 py-2 rounded-lg font-bold text-sm transition-all flex items-center justify-center gap-2 ${activeTab === AppTab.SAVED ? 'bg-yellow-500 text-slate-950 shadow-lg' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
          >
            המניות השמורות שלי
            {savedSymbols.length > 0 && <span className="bg-slate-800 text-[10px] px-2 py-0.5 rounded-full">{savedSymbols.length}</span>}
          </button>
        </div>
      </div>

      {/* Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-8 mt-8">
        {loading && stocks.length === 0 ? (
          <div className="flex flex-col items-center justify-center min-h-[400px] gap-6">
            <div className="relative">
              <div className="w-20 h-20 border-4 border-blue-500/20 border-t-blue-500 rounded-full animate-spin"></div>
              <div className="absolute inset-0 flex items-center justify-center">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                </svg>
              </div>
            </div>
            <div className="text-center">
              <h2 className="text-xl font-bold mb-2">מנתח את השוק...</h2>
              <p className="text-slate-400 max-w-md mx-auto">אנחנו משתמשים בבינה מלאכותית (Gemini) כדי לאתר מניות עם פוטנציאל פריצה של פי 2 על פי תחזיות האנליסטים.</p>
            </div>
          </div>
        ) : error ? (
          <div className="bg-red-500/10 border border-red-500/20 rounded-xl p-8 text-center max-w-lg mx-auto mt-20">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-red-500 mx-auto mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
            </svg>
            <h3 className="text-xl font-bold text-red-400 mb-2">אופס! משהו השתבש</h3>
            <p className="text-slate-400 mb-6">{error}</p>
            <button onClick={loadData} className="px-6 py-2 bg-red-500 hover:bg-red-600 text-white font-bold rounded-lg transition-colors">
              נסה שוב
            </button>
          </div>
        ) : filteredStocks.length === 0 ? (
          <div className="flex flex-col items-center justify-center min-h-[300px] border-2 border-dashed border-slate-800 rounded-3xl mt-10 p-10 bg-slate-900/20">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-slate-700 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
            </svg>
            <h3 className="text-xl font-bold text-slate-400">אין מניות להצגה</h3>
            <p className="text-slate-500 mt-2">
              {activeTab === AppTab.SAVED ? 'עדיין לא שמרת מניות. לחץ על הכוכב במניות שמעניינות אותך!' : 'לא נמצאו מניות העונות לקריטריונים כרגע.'}
            </p>
            {activeTab === AppTab.SAVED && (
              <button 
                onClick={() => setActiveTab(AppTab.DASHBOARD)}
                className="mt-6 text-blue-400 font-bold hover:underline"
              >
                חזרה לכל המניות
              </button>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredStocks.map((stock) => (
              <StockCard 
                key={stock.symbol} 
                stock={stock} 
                onToggleSave={toggleSave}
                isSaved={savedSymbols.includes(stock.symbol)}
              />
            ))}
          </div>
        )}
      </main>

      {/* Footer Info */}
      <footer className="mt-20 border-t border-slate-800 py-10 px-8 text-center text-slate-500 text-sm">
        <div className="max-w-3xl mx-auto space-y-4">
          <p>
            כל הנתונים המוצגים כאן מבוססים על ניתוח של בינה מלאכותית ואינם מהווים המלצה לפעולה בניירות ערך.
          </p>
          <p className="text-xs">
            הנתונים הטכניים והפיננסיים מעובדים בזמן אמת באמצעות Gemini 3 Flash ומקורות מידע ציבוריים.
          </p>
          <div className="flex justify-center gap-6 pt-4">
            <span className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-blue-500"></div> ניתוח טכני</span>
            <span className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-emerald-500"></div> נתונים פיננסיים</span>
            <span className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-amber-500"></div> צפי אנליסטים</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Stock {
  symbol: string;
  name: string;
  price: number;
  targetPrice: number;
  upside: number; // numeric percentage (e.g., 125 for 125%)
  peRatio: string;
  marketCap: string;
  rsi: number;
  vwap: number;
  movingAverage: string;
  description: string;
  sector: string;
  analystSentiment: 'Bullish' | 'Neutral' | 'Bearish';
  priceHistory: number[]; // Last 10 days for sparkline
  sourceUrls?: { title: string; uri: string }[];
}

export enum AppTab {
  DASHBOARD = 'DASHBOARD',
  SAVED = 'SAVED'
}

import { GoogleGenAI, Type } from "@google/genai";
import { Stock } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const fetchHighGrowthStocks = async (): Promise<Stock[]> => {
  const prompt = `Find a list of at least 10 real, currently traded stocks (US markets) where analyst price targets for 2025 suggest a potential gain of 100% (2x) or more.
  For each stock, provide:
  - Ticker Symbol
  - Company Name
  - Current Price (number)
  - Analyst Target Price (number)
  - Calculated Upside percentage (number, e.g. 150 for 150%)
  - P/E Ratio (string)
  - Market Cap (string)
  - RSI (number, 0-100)
  - VWAP (number)
  - Technical Indicator: 50-day Moving Average status (string)
  - Sector (e.g. Technology, Biotech, Energy)
  - Short description of the catalyst for the 2x prediction.
  - Overall Analyst Sentiment.
  - A 10-day historical closing price trend (array of 10 numbers ending with current price).

  Ensure all numerical fields are returned as numbers, not strings with symbols.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              symbol: { type: Type.STRING },
              name: { type: Type.STRING },
              price: { type: Type.NUMBER },
              targetPrice: { type: Type.NUMBER },
              upside: { type: Type.NUMBER },
              peRatio: { type: Type.STRING },
              marketCap: { type: Type.STRING },
              rsi: { type: Type.NUMBER },
              vwap: { type: Type.NUMBER },
              movingAverage: { type: Type.STRING },
              sector: { type: Type.STRING },
              description: { type: Type.STRING },
              analystSentiment: { type: Type.STRING },
              priceHistory: {
                type: Type.ARRAY,
                items: { type: Type.NUMBER }
              }
            },
            required: ["symbol", "name", "price", "targetPrice", "upside", "sector", "priceHistory"]
          }
        }
      },
    });

    const resultText = response.text;
    const stocks: Stock[] = JSON.parse(resultText);

    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sourceUrls = chunks
      .filter(c => c.web)
      .map(c => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '' }));

    return stocks.map(stock => ({
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    }));
  } catch (error) {
    console.error("Error fetching stocks:", error);
    throw error;
  }
};

import React from 'react';
import { Stock } from '../types';

interface StockCardProps {
  stock: Stock;
  onToggleSave: (symbol: string) => void;
  isSaved: boolean;
}

export const StockCard: React.FC<StockCardProps> = ({ stock, onToggleSave, isSaved }) => {
  // Simple Sparkline generation
  const generateSparkline = (data: number[]) => {
    if (!data || data.length < 2) return null;
    const min = Math.min(...data);
    const max = Math.max(...data);
    const range = max - min || 1;
    const width = 200;
    const height = 40;
    const points = data.map((val, i) => {
      const x = (i / (data.length - 1)) * width;
      const y = height - ((val - min) / range) * height;
      return `${x},${y}`;
    }).join(' ');

    return (
      <svg width="100%" height={height} viewBox={`0 0 ${width} ${height}`} className="overflow-visible">
        <polyline
          fill="none"
          stroke="#60a5fa"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          points={points}
        />
        {/* Mock VWAP line (slightly offset or average) */}
        <line 
          x1="0" y1={height/2} x2={width} y2={height/2.2} 
          stroke="#f59e0b" strokeWidth="1" strokeDasharray="4" opacity="0.5" 
        />
      </svg>
    );
  };

  return (
    <div className="bg-slate-800 border border-slate-700 rounded-xl p-5 shadow-lg transition-all hover:border-blue-500 hover:shadow-blue-900/20 group flex flex-col h-full">
      <div className="flex justify-between items-start mb-2">
        <div>
          <h3 className="text-xl font-bold text-white group-hover:text-blue-400 transition-colors flex items-center gap-2">
            {stock.symbol}
            <span className="text-[10px] px-1.5 py-0.5 bg-slate-700 rounded text-slate-400 font-normal">{stock.sector}</span>
          </h3>
          <p className="text-slate-400 text-sm truncate max-w-[150px]">{stock.name}</p>
        </div>
        <button 
          onClick={() => onToggleSave(stock.symbol)}
          className={`p-2 rounded-full transition-colors ${isSaved ? 'text-yellow-400 bg-yellow-400/10' : 'text-slate-500 hover:text-white bg-slate-700'}`}
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill={isSaved ? "currentColor" : "none"} viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11.049 2.927c.3-.921 1.603-.921 1.902 0l1.519 4.674a1 1 0 00.95.69h4.915c.969 0 1.371 1.24.588 1.81l-3.976 2.888a1 1 0 00-.363 1.118l1.518 4.674c.3.922-.755 1.688-1.538 1.118l-3.976-2.888a1 1 0 00-1.176 0l-3.976 2.888c-.783.57-1.838-.197-1.538-1.118l1.518-4.674a1 1 0 00-.363-1.118l-3.976-2.888c-.784-.57-.382-1.81.588-1.81h4.914a1 1 0 00.951-.69l1.519-4.674z" />
          </svg>
        </button>
      </div>

      {/* Mini Chart */}
      <div className="my-3 py-2 border-b border-slate-700/50">
        <div className="flex justify-between items-end mb-1">
          <span className="text-[10px] text-slate-500 uppercase font-bold tracking-tighter">מגמת מחיר (10 ימים)</span>
          <span className="text-[10px] text-amber-500 font-bold">VWAP: ${stock.vwap.toFixed(2)}</span>
        </div>
        {generateSparkline(stock.priceHistory)}
      </div>

      <div className="grid grid-cols-2 gap-3 mb-4">
        <div className="bg-slate-900/50 p-2 rounded">
          <p className="text-[10px] text-slate-500 mb-0.5 font-semibold uppercase">מחיר</p>
          <p className="text-base font-bold text-slate-200">${stock.price.toFixed(2)}</p>
        </div>
        <div className="bg-slate-900/50 p-2 rounded">
          <p className="text-[10px] text-slate-500 mb-0.5 font-semibold uppercase">יעד</p>
          <p className="text-base font-bold text-green-400">${stock.targetPrice.toFixed(2)}</p>
        </div>
      </div>

      <div className="flex items-center justify-between p-2.5 bg-green-500/10 border border-green-500/20 rounded-lg mb-4">
        <span className="text-xs font-medium text-green-300">פוטנציאל פריצה:</span>
        <span className="text-lg font-black text-green-400">+{stock.upside}%</span>
      </div>

      <div className="space-y-1.5 mb-4 text-[13px] flex-grow">
        <div className="flex justify-between border-b border-slate-700/50 pb-1">
          <span className="text-slate-500">שווי שוק:</span>
          <span className="text-slate-300 font-medium">{stock.marketCap}</span>
        </div>
        <div className="flex justify-between border-b border-slate-700/50 pb-1">
          <span className="text-slate-500">RSI:</span>
          <div className="flex items-center gap-2">
             <div className="w-16 h-1.5 bg-slate-700 rounded-full overflow-hidden">
                <div 
                  className={`h-full rounded-full ${stock.rsi > 70 ? 'bg-red-500' : stock.rsi < 30 ? 'bg-green-500' : 'bg-blue-500'}`}
                  style={{ width: `${stock.rsi}%` }}
                ></div>
             </div>
             <span className={`font-bold ${stock.rsi > 70 ? 'text-red-400' : stock.rsi < 30 ? 'text-green-400' : 'text-blue-400'}`}>
              {stock.rsi.toFixed(0)}
            </span>
          </div>
        </div>
        <div className="flex justify-between border-b border-slate-700/50 pb-1">
          <span className="text-slate-500">ממוצע נע 50:</span>
          <span className="text-slate-300 font-medium text-[11px]">{stock.movingAverage}</span>
        </div>
      </div>

      <p className="text-[11px] text-slate-400 leading-relaxed mb-4 italic line-clamp-2">
        "{stock.description}"
      </p>

      {stock.sourceUrls && stock.sourceUrls.length > 0 && (
        <div className="mt-auto pt-2 border-t border-slate-700/30">
          <div className="flex flex-wrap gap-2">
