import { GoogleGenerativeAI, HarmBlockThreshold, HarmCategory } from "@google/generative-ai";

interface Stock {
  symbol: string;
  name: string;
  price: number;
  targetPrice: number;
  upside: number;
  sector: string;
  priceHistory: { date: string; close: number }[];
  sourceUrls: { title: string; uri: string }[];
  analystSentiment: string;
}

const API_KEY = process.env.GOOGLE_API_KEY;

export const fetchHighGrowthStocks = async () => {
  if (!API_KEY) {
    throw new Error("Missing GOOGLE_API_KEY");
  }

  const genAI = new GoogleGenerativeAI(API_KEY);

  const model = genAI.getGenerativeModel({
    model: "gemini-3-pro-preview",
    safetySettings: [
      {
        category: HarmCategory.HARASSMENT,
        threshold: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
      },
      {
        category: HarmCategory.HATE_SPEECH,
        threshold: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
      },
      {
        category: HarmCategory.SEXUALLY_EXPLICIT,
        threshold: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
      },
      {
        category: HarmCategory.DANGEROUS_CONTENT,
        threshold: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
      },
    ],
  });

  try {
    const result = await model.generateContent({
      contents: [{
        parts: [{ text: "Generate high growth stocks data, in JSON format, adhere to this schema. Do not deviate!" }],
      }],
      generationConfig: {
        maxOutputTokens: 2048,
        temperature: 0.7,
        topP: 1,
        topK: 1,
      },
      tools: [{
        functionDeclaration: {
          name: "get_stock_data",
          description: "Provides financial data for high growth stocks.",
          parameters: {
            type: "object",
            properties: {
              stocks: {
                type: "array",
                description: "Array of stock data.",
                items: {
                  type: "object",
                  properties: {
                    symbol: { type: "string", description: "Stock symbol, e.g., AAPL" },
                    name: { type: "string", description: "Company name, e.g., Apple Inc." },
                    price: { type: "number", description: "Current stock price" },
                    targetPrice: { type: "number", description: "Analyst target price" },
                    upside: { type: "number", description: "Percentage upside potential" },
                    sector: { type: "string", description: "Industry sector" },
                    priceHistory: {
                      type: "array",
                      description: "Historical stock prices",
                      items: {
                        type: "object",
                        properties: {
                          date: { type: "string", description: "Date of the price" },
                          close: { type: "number", description: "Closing price on the date" }
                        },
                        required: ["date", "close"]
                      }
