import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { Stock } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const STOCK_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    symbol: { type: Type.STRING },
    name: { type: Type.STRING },
    price: { type: Type.NUMBER },
    targetPrice: { type: Type.NUMBER },
    upside: { type: Type.NUMBER },
    peRatio: { type: Type.STRING },
    marketCap: { type: Type.STRING },
    rsi: { type: Type.NUMBER },
    vwap: { type: Type.NUMBER },
    movingAverage: { type: Type.STRING },
    sector: { type: Type.STRING },
    description: { type: Type.STRING },
    analystSentiment: { type: Type.STRING },
    priceHistory: {
      type: Type.ARRAY,
      items: { type: Type.NUMBER }
    }
  },
  required: ["symbol", "name", "price", "targetPrice", "upside", "sector", "priceHistory"]
};

export const fetchHighGrowthStocks = async (): Promise<Stock[]> => {
  const prompt = `Find a comprehensive list of at least 20 real, currently traded stocks (US markets) where analyst price targets for 2025 suggest a potential gain of 80% to 200% or more.
  Include a mix of:
  - Mega-caps with high targets (e.g., MSTR/MicroStrategy if applicable)
  - Small/Mid-cap growth stocks (e.g., REKR/Rekor Systems, biotech, AI startups)
  - Diverse sectors: Technology, Crypto-adjacent, Energy, Biotech.

  For each stock, provide:
  - Ticker, Name, Current Price (num), Target Price (num), Upside %, P/E, Market Cap, RSI (0-100), VWAP, 50-day MA status, Sector, Catalyst Description, Sentiment, and a 10-day price history array.

  IMPORTANT: Do not filter by market cap. We want high-potential stocks regardless of size.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: STOCK_SCHEMA
        }
      },
    });

    const resultText = response.text;
    if (!resultText) return [];

    const stocks: Stock[] = JSON.parse(resultText);
    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    const chunks = (groundingMetadata?.groundingChunks as any[]) || [];
    const sourceUrls = chunks.filter(c => c.web).map(c => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '' }));

    return stocks.map(stock => ({
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    }));
