import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { Stock } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const STOCK_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    symbol: { type: Type.STRING },
    name: { type: Type.STRING },
    price: { type: Type.NUMBER },
    targetPrice: { type: Type.NUMBER },
    upside: { type: Type.NUMBER },
    peRatio: { type: Type.STRING },
    marketCap: { type: Type.STRING },
    rsi: { type: Type.NUMBER },
    vwap: { type: Type.NUMBER },
    vwapUpper: { type: Type.NUMBER },
    vwapLower: { type: Type.NUMBER },
    movingAverage: { type: Type.STRING },
    sector: { type: Type.STRING },
    description: { type: Type.STRING },
    analystSentiment: { type: Type.STRING },
    nextEarningsDate: { type: Type.STRING },
    riskScore: { type: Type.NUMBER },
    rewardScore: { type: Type.NUMBER },
    isAIRecommendation: { type: Type.BOOLEAN },
    priceHistory: {
      type: Type.ARRAY,
      items: { type: Type.NUMBER }
    }
  },
  required: ["symbol", "name", "price", "targetPrice", "upside", "sector", "priceHistory", "nextEarningsDate", "riskScore", "rewardScore", "isAIRecommendation"]
};

export const fetchHighGrowthStocks = async (): Promise<Stock[]> => {
  const prompt = `Find a list of at least 15 real, currently traded stocks (US markets) where analyst price targets suggest a potential gain of 80% to 300% or more.
  Include:
  - Ticker, Name, Price, Target, Upside %, P/E, Market Cap, RSI, VWAP (with Upper/Lower bands roughly +/- 2%), 50-day MA, Sector, Catalyst.
  - NEW: Next Earnings Date (estimated if exact date not set).
  - NEW: Risk Score (1-10, where 10 is very risky) and Reward Score (1-10, where 10 is very high reward).
  - NEW: isAIRecommendation (Boolean). Set this to true ONLY if the stock shows a technical breakout pattern (e.g. trading above VWAP and moving averages) combined with high upside.
  - 10-day price history.

  Focus on stocks like MSTR, REKR, and other high-growth tech/biotech/energy assets.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: STOCK_SCHEMA
        }
      },
    });

    const resultText = response.text;
    if (!resultText) return [];

    const stocks: Stock[] = JSON.parse(resultText);
    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    const chunks = (groundingMetadata?.groundingChunks as any[]) || [];
    const sourceUrls = chunks.filter(c => c.web).map(c => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '' }));

    return stocks.map(stock => ({
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    }));
  } catch (error) {
    console.error("Error fetching stocks:", error);
    throw error;
  }
};

export const fetchStockByTicker = async (ticker: string): Promise<Stock | null> => {
  const prompt = `Analyze the stock ${ticker.toUpperCase()} specifically. Provide full technical and financial data. Include next earnings date, risk/reward scores (1-10), and decide if it's a 'Breakout Recommendation' (isAIRecommendation: true) based on recent price action. Return VWAP with Upper/Lower bands. Provide a 10-day price history array.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: STOCK_SCHEMA
      },
    });

    const resultText = response.text;
    if (!resultText) return null;

    const stock: Stock = JSON.parse(resultText);
    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    const chunks = (groundingMetadata?.groundingChunks as any[]) || [];
    const sourceUrls = chunks.filter(c => c.web).map(c => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '' }));

    return {
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    };
  } catch (error) {
    console.error(`Error fetching ${ticker}:`, error);
    return null;
  }
};

import React from 'react';
import { Stock } from '../types';

interface StockCardProps {
  stock: Stock;
  onToggleSave: (symbol: string) => void;
  isSaved: boolean;
}

export const StockCard: React.FC<StockCardProps> = ({ stock, onToggleSave, isSaved }) => {
  // Triple VWAP Sparkline generation
  const generateSparkline = (data: number[]) => {
    if (!data || data.length < 2) return null;
    const min = Math.min(...data, stock.vwapLower || stock.vwap * 0.95);
    const max = Math.max(...data, stock.vwapUpper || stock.vwap * 1.05);
    const range = max - min || 1;
    const width = 200;
    const height = 50;

    const points = data.map((val, i) => {
      const x = (i / (data.length - 1)) * width;
      const y = height - ((val - min) / range) * height;
      return `${x},${y}`;
    }).join(' ');

    const vwapY = height - ((stock.vwap - min) / range) * height;
    const upperY = height - (((stock.vwapUpper || stock.vwap * 1.02) - min) / range) * height;
    const lowerY = height - (((stock.vwapLower || stock.vwap * 0.98) - min) / range) * height;

    return (
      <svg width="100%" height={height} viewBox={`0 0 ${width} ${height}`} className="overflow-visible">
        {/* VWAP BANDS */}
        <line x1="0" y1={upperY} x2={width} y2={upperY} stroke="#f59e0b" strokeWidth="0.5" strokeDasharray="2" opacity="0.3" />
        <line x1="0" y1={vwapY} x2={width} y2={vwapY} stroke="#f59e0b" strokeWidth="1" strokeDasharray="4" opacity="0.6" />
        <line x1="0" y1={lowerY} x2={width} y2={lowerY} stroke="#f59e0b" strokeWidth="0.5" strokeDasharray="2" opacity="0.3" />

        {/* PRICE LINE */}
        <polyline
          fill="none"
          stroke={stock.isAIRecommendation ? "#10b981" : "#60a5fa"}
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          points={points}
        />
      </svg>
    );
  };

  const getScoreColor = (score: number, inverse = false) => {
    if (inverse) { // For Risk: high is bad (red)
      if (score >= 7) return 'bg-red-500';
      if (score >= 4) return 'bg-yellow-500';
      return 'bg-green-500';
    } else { // For Reward: high is good (green)
      if (score >= 7) return 'bg-green-500';
      if (score >= 4) return 'bg-blue-500';
      return 'bg-slate-500';
    }
  };

  return (
    <div className={`relative flex flex-col h-full rounded-2xl p-5 transition-all shadow-xl border-2 ${
      stock.isAIRecommendation 
      ? 'bg-slate-800 border-emerald-500/50 shadow-emerald-900/10 ring-1 ring-emerald-500/20' 
      : 'bg-slate-800 border-slate-700 hover:border-blue-500'
    } group`}>

      {stock.isAIRecommendation && (
        <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-emerald-500 text-slate-950 text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-widest shadow-lg animate-pulse">
          Breakout Candidate
        </div>
      )}

      <div className="flex justify-between items-start mb-2">
        <div>
          <h3 className="text-xl font-bold text-white group-hover:text-blue-400 transition-colors flex items-center gap-2">
            {stock.symbol}
            <span className="text-[9px] px-1.5 py-0.5 bg-slate-700 rounded text-slate-400 font-bold tracking-wider">{stock.sector}</span>
          </h3>
          <p className="text-slate-400 text-sm truncate max-w-[150px]">{stock.name}</p>
        </div>
        <button 
          onClick={() => onToggleSave(stock.symbol)}
          className={`p-2 rounded-full transition-colors ${isSaved ? 'text-yellow-400 bg-yellow-400/10' : 'text-slate-500 hover:text-white bg-slate-700'}`}
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill={isSaved ? "currentColor" : "none"} viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11.049 2.927c.3-.921 1.603-.921 1.902 0l1.519 4.674a1 1 0 00.95.69h4.915c.969 0 1.371 1.24.588 1.81l-3.976 2.888a1 1 0 00-.363 1.118l1.518 4.674c.3.922-.755 1.688-1.538 1.118l-3.976-2.888a1 1 0 00-1.176 0l-3.976 2.888c-.783.57-1.838-.197-1.538-1.118l1.518-4.674a1 1 0 00-.363-1.118l-3.976-2.888c-.784-.57-.382-1.81.588-1.81h4.914a1 1 0 00.951-.69l1.519-4.674z" />
          </svg>
        </button>
      </div>

      {/* Mini Chart Area */}
      <div className="my-4 py-2 border-b border-slate-700/50">
        <div className="flex justify-between items-end mb-2">
          <span className="text-[10px] text-slate-500 font-bold tracking-tighter uppercase">מגמת 10 ימים + Triple VWAP</span>
          <span className="text-[10px] text-amber-500 font-bold">V:${stock.vwap.toFixed(2)}</span>
        </div>
        {generateSparkline(stock.priceHistory)}
      </div>

      <div className="grid grid-cols-2 gap-3 mb-4">
        <div className="bg-slate-900/50 p-2.5 rounded-xl">
          <p className="text-[9px] text-slate-500 mb-0.5 font-bold uppercase">Price</p>
          <p className="text-lg font-bold text-slate-100">${stock.price.toFixed(2)}</p>
        </div>
        <div className="bg-slate-900/50 p-2.5 rounded-xl border border-emerald-500/10">
          <p className="text-[9px] text-emerald-500 mb-0.5 font-bold uppercase">Target (2025)</p>
          <p className="text-lg font-bold text-emerald-400">${stock.targetPrice.toFixed(2)}</p>
        </div>
      </div>

      {/* Breakout / Upside Highlight */}
      <div className={`p-3 rounded-xl mb-4 flex items-center justify-between ${
        stock.isAIRecommendation ? 'bg-emerald-500/20 border border-emerald-500/30' : 'bg-slate-900 border border-slate-700'
      }`}>
        <span className="text-xs font-bold text-slate-300">פוטנציאל פריצה</span>
        <span className={`text-xl font-black ${stock.isAIRecommendation ? 'text-emerald-400' : 'text-blue-400'}`}>
          +{stock.upside}%
        </span>
      </div>

      {/* Scores & Info */}
      <div className="space-y-3 mb-5 flex-grow">
        <div className="flex flex-col gap-1.5">
          <div className="flex justify-between text-[11px] font-bold text-slate-500 px-1">
            <span>RISK</span>
            <span className="text-slate-300">{stock.riskScore}/10</span>
          </div>
          <div className="w-full h-1.5 bg-slate-900 rounded-full overflow-hidden">
            <div className={`h-full ${getScoreColor(stock.riskScore, true)}`} style={{ width: `${stock.riskScore * 10}%` }}></div>
          </div>
        </div>
        <div className="flex flex-col gap-1.5">
          <div className="flex justify-between text-[11px] font-bold text-slate-500 px-1">
            <span>REWARD</span>
            <span className="text-slate-300">{stock.rewardScore}/10</span>
          </div>
          <div className="w-full h-1.5 bg-slate-900 rounded-full overflow-hidden">
            <div className={`h-full ${getScoreColor(stock.rewardScore)}`} style={{ width: `${stock.rewardScore * 10}%` }}></div>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-2 pt-2">
          <div className="text-center p-2 bg-slate-900/30 rounded-lg">
            <p className="text-[8px] text-slate-500 font-bold uppercase">דו"ח רווחים</p>
            <p className="text-[11px] text-amber-300 font-medium">{stock.nextEarningsDate}</p>
          </div>
          <div className="text-center p-2 bg-slate-900/30 rounded-lg">
            <p className="text-[8px] text-slate-500 font-bold uppercase">RSI</p>
            <p className={`text-[11px] font-black ${stock.rsi > 70 ? 'text-red-400' : stock.rsi < 30 ? 'text-green-400' : 'text-blue-400'}`}>{stock.rsi.toFixed(1)}</p>
          </div>
        </div>
      </div>

      <p className="text-[11px] text-slate-400 leading-relaxed italic line-clamp-2 mb-4">
        "{stock.description}"
      </p>

      {stock.sourceUrls && stock.sourceUrls.length > 0 && (
        <div className="mt-auto pt-3 border-t border-slate-700/50 flex justify-between items-center">
          <a href={stock.sourceUrls[0].uri} target="_blank" rel="noopener noreferrer" className="text-[10px] text-blue-400 hover:text-blue-300 flex items-center gap-1 font-bold">
            מקור נתונים <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
          </a>
          <span className="text-[9px] text-slate-600 font-bold uppercase">{stock.marketCap} CAP</span>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { fetchHighGrowthStocks, fetchStockByTicker } from './services/geminiService';
import { Stock, AppTab } from './types';
import { StockCard } from './components/StockCard';

const App: React.FC = () => {
  const [stocks, setStocks] = useState<Stock[]>([]);
  const [savedSymbols, setSavedSymbols] = useState<string[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [searchingTicker, setSearchingTicker] = useState<boolean>(false);
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<AppTab>(AppTab.DASHBOARD);
  const [lastRefreshed, setLastRefreshed] = useState<Date>(new Date());

  const loadData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchHighGrowthStocks();
      // Sort by recommendation first, then by upside
      const sortedData = data.sort((a, b) => {
        if (a.isAIRecommendation && !b.isAIRecommendation) return -1;
        if (!a.isAIRecommendation && b.isAIRecommendation) return 1;
        return b.upside - a.upside;
      });
