import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { Stock } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const STOCK_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    symbol: { type: Type.STRING },
    name: { type: Type.STRING },
    price: { type: Type.NUMBER },
    targetPrice: { type: Type.NUMBER },
    upside: { type: Type.NUMBER },
    peRatio: { type: Type.STRING },
    marketCap: { type: Type.STRING },
    rsi: { type: Type.NUMBER },
    vwap: { type: Type.NUMBER },
    vwapUpper: { type: Type.NUMBER },
    vwapLower: { type: Type.NUMBER },
    movingAverage: { type: Type.STRING },
    sector: { type: Type.STRING },
    description: { type: Type.STRING },
    analystSentiment: { type: Type.STRING },
    nextEarningsDate: { type: Type.STRING },
    riskScore: { type: Type.NUMBER },
    rewardScore: { type: Type.NUMBER },
    isAIRecommendation: { type: Type.BOOLEAN },
    priceHistory: {
      type: Type.ARRAY,
      items: { type: Type.NUMBER }
    }
  },
  required: ["symbol", "name", "price", "targetPrice", "upside", "sector", "priceHistory", "nextEarningsDate", "riskScore", "rewardScore", "isAIRecommendation"]
};

export const fetchHighGrowthStocks = async (): Promise<Stock[]> => {
  const prompt = `Find a list of at least 15 real, currently traded stocks (US markets) where average analyst price targets for 2025/2026 suggest a potential gain of AT LEAST 100% (2x) or more from current price levels.

  STRICT RULES:
  - DO NOT include any stock with upside potential less than 100%.
  - Focus on high-conviction growth stocks (Tech, Biotech, Energy, AI, etc.).
  - Include major movers like MSTR, REKR, or similar if their current targets justify a 2x breakout.

  Return data for each:
  - Ticker, Name, Price, Target, Upside % (must be >= 100), P/E, Market Cap, RSI, VWAP (with Upper/Lower bands +/- 2-3%), 50-day MA, Sector, Catalyst.
  - Next Earnings Date.
  - Risk Score (1-10, 10=high risk) and Reward Score (1-10, 10=high reward).
  - isAIRecommendation (Boolean): True if technical indicators (like trading near VWAP) suggest an imminent breakout.
  - 10-day price history array.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: STOCK_SCHEMA
        }
      },
    });

    const resultText = response.text;
    if (!resultText) return [];

    // Filter at service level just in case the model ignored the prompt instruction
    const stocks: Stock[] = JSON.parse(resultText).filter((s: Stock) => s.upside >= 100);

    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    const chunks = (groundingMetadata?.groundingChunks as any[]) || [];
    const sourceUrls = chunks.filter(c => c.web).map(c => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '' }));

    return stocks.map(stock => ({
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    }));
  } catch (error) {
    console.error("Error fetching stocks:", error);
    throw error;
  }
};

export const fetchStockByTicker = async (ticker: string): Promise<Stock | null> => {
  const prompt = `Analyze the stock ${ticker.toUpperCase()} specifically. Provide full technical and financial data. 
  Check if analyst targets for 2025 suggest a 100% (2x) upside. 
  Include: price, target, upside, earnings date, risk/reward scores (1-10), RSI, and VWAP with bands. 
  Provide a 10-day price history array.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: STOCK_SCHEMA
      },
    });

    const resultText = response.text;
    if (!resultText) return null;

    const stock: Stock = JSON.parse(resultText);
    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    const chunks = (groundingMetadata?.groundingChunks as any[]) || [];
    const sourceUrls = chunks.filter(c => c.web).map(c => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '' }));

    return {
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    };
  } catch (error) {
    console.error(`Error fetching ${ticker}:`, error);
    return null;
  }
};

