          <p className="text-xl font-black text-emerald-400">${stock.targetPrice.toFixed(2)}</p>
        </div>
      </div>

      <div className={`p-4 rounded-2xl mb-6 flex flex-col gap-1 ${
        stock.isAIRecommendation ? 'bg-emerald-500/20 border border-emerald-500/40' : 'bg-slate-950 border border-slate-800'
      }`}>
        <div className="flex justify-between items-center">
          <span className="text-xs font-black text-slate-400 uppercase tracking-tighter">Upside Potential</span>
          <span className={`text-2xl font-black ${stock.isAIRecommendation ? 'text-emerald-400' : 'text-blue-400'}`}>
            +{stock.upside}%
          </span>
        </div>
        <div className="w-full h-1.5 bg-slate-800 rounded-full mt-2">
          <div className={`h-full rounded-full ${stock.isAIRecommendation ? 'bg-emerald-500' : 'bg-blue-500'}`} style={{ width: `${Math.min(stock.upside / 3, 100)}%` }}></div>
        </div>
      </div>

      <div className="space-y-4 mb-6 flex-grow">
