import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { Stock } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const STOCK_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    symbol: { type: Type.STRING },
    name: { type: Type.STRING },
    price: { type: Type.NUMBER },
    targetPrice: { type: Type.NUMBER },
    upside: { type: Type.NUMBER },
    peRatio: { type: Type.STRING },
    marketCap: { type: Type.STRING },
    rsi: { type: Type.NUMBER },
    vwap: { type: Type.NUMBER },
    vwapUpper: { type: Type.NUMBER },
    vwapLower: { type: Type.NUMBER },
    movingAverage: { type: Type.STRING },
    sector: { type: Type.STRING },
    description: { type: Type.STRING },
    analystSentiment: { type: Type.STRING },
    nextEarningsDate: { type: Type.STRING },
    riskScore: { type: Type.NUMBER },
    rewardScore: { type: Type.NUMBER },
    isAIRecommendation: { type: Type.BOOLEAN },
    recommendationReason: { type: Type.STRING },
    priceHistory: {
      type: Type.ARRAY,
      items: { type: Type.NUMBER }
    }
  },
  required: ["symbol", "name", "price", "targetPrice", "upside", "marketCap", "sector", "priceHistory", "nextEarningsDate", "riskScore", "rewardScore", "isAIRecommendation", "recommendationReason"]
};

export const fetchHighGrowthStocks = async (): Promise<Stock[]> => {
  const prompt = `Conduct an elite financial and technical analysis of the US stock market. Target: Stocks with >100% (2x) analyst upside.

  STRICT SELECTIVITY RULES:
  - 'isAIRecommendation' MUST be FALSE for most stocks. ONLY set to TRUE for the top 15% (e.g., max 3 out of 20) that exhibit both technical breakout patterns AND solid business fundamentals (moat, revenue growth).
  - A recommendation REQUIRES: RSI < 60, price near VWAP support, and a high 'rewardScore' (>8).
  - Provide a short 'recommendationReason' for these specific picks.

  DATA INTEGRITY:
  - 'marketCap' is MANDATORY (e.g., "45.2B", "890M"). DO NOT skip this.
  - Return at least 15-20 stocks to ensure a wide enough scan.
  - Upside MUST be numeric percentage (100 = 100% gain).
  - Triple VWAP (Lower, VWAP, Upper) must be included.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: STOCK_SCHEMA
        }
      },
    });

    const resultText = response.text;
    if (!resultText) return [];

    let stocks: Stock[] = JSON.parse(resultText);

    // Safety check for upside requirement
    stocks = stocks.filter(s => s.upside >= 100);

    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    const chunks = (groundingMetadata?.groundingChunks as any[]) || [];
    const sourceUrls = chunks.filter(c => c.web).map(c => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '' }));

    return stocks.map(stock => ({
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    }));
  } catch (error) {
    console.error("Error fetching stocks:", error);
    throw error;
  }
};

export const fetchStockByTicker = async (ticker: string): Promise<Stock | null> => {
  const prompt = `Deep dive on ${ticker.toUpperCase()}. Provide full technical/financial data. strictly evaluate if it warrants a 'Recommendation' based on 2x growth potential and technical support. MUST include market cap.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: STOCK_SCHEMA
      },
    });

    const resultText = response.text;
    if (!resultText) return null;

    const stock: Stock = JSON.parse(resultText);
    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    const chunks = (groundingMetadata?.groundingChunks as any[]) || [];
    const sourceUrls = chunks.filter(c => c.web).map(c => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '' }));

    return {
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    };
  } catch (error) {
    console.error(`Error fetching ${ticker}:`, error);
    return null;
  }
};

import React from 'react';
import { Stock } from '../types';

interface StockCardProps {
  stock: Stock;
  onToggleSave: (symbol: string) => void;
  isSaved: boolean;
}

export const StockCard: React.FC<StockCardProps> = ({ stock, onToggleSave, isSaved }) => {
  const generateSparkline = (data: number[]) => {
    if (!data || data.length < 2) return null;
    const min = Math.min(...data, stock.vwapLower || stock.vwap * 0.95);
    const max = Math.max(...data, stock.vwapUpper || stock.vwap * 1.05);
    const range = max - min || 1;
    const width = 200;
    const height = 60;

    const points = data.map((val, i) => {
      const x = (i / (data.length - 1)) * width;
      const y = height - ((val - min) / range) * height;
      return `${x},${y}`;
    }).join(' ');

    const vwapY = height - ((stock.vwap - min) / range) * height;
    const upperY = height - (((stock.vwapUpper || stock.vwap * 1.02) - min) / range) * height;
    const lowerY = height - (((stock.vwapLower || stock.vwap * 0.98) - min) / range) * height;

    return (
      <svg width="100%" height={height} viewBox={`0 0 ${width} ${height}`} className="overflow-visible preserve-3d">
        <line x1="0" y1={upperY} x2={width} y2={upperY} stroke="#f59e0b" strokeWidth="0.5" strokeDasharray="2" opacity="0.3" />
        <line x1="0" y1={vwapY} x2={width} y2={vwapY} stroke="#f59e0b" strokeWidth="1" strokeDasharray="4" opacity="0.6" />
        <line x1="0" y1={lowerY} x2={width} y2={lowerY} stroke="#f59e0b" strokeWidth="0.5" strokeDasharray="2" opacity="0.3" />
        <polyline
          fill="none"
          stroke={stock.isAIRecommendation ? "#10b981" : "#60a5fa"}
          strokeWidth="3"
          strokeLinecap="round"
          strokeLinejoin="round"
          points={points}
          className="drop-shadow-[0_0_8px_rgba(16,185,129,0.3)]"
        />
      </svg>
    );
  };

  const getScoreColor = (score: number, inverse = false) => {
    if (inverse) {
      if (score >= 7) return 'bg-red-500';
      if (score >= 4) return 'bg-yellow-500';
      return 'bg-green-500';
    } else {
      if (score >= 7) return 'bg-green-500';
      if (score >= 4) return 'bg-blue-500';
      return 'bg-slate-600';
    }
  };

  return (
    <div className={`relative flex flex-col h-full rounded-[2rem] p-5 sm:p-7 transition-all duration-500 shadow-2xl border-2 overflow-hidden ${
      stock.isAIRecommendation 
      ? 'bg-slate-900 border-emerald-500/80 shadow-emerald-900/30 ring-1 ring-emerald-500/30' 
      : 'bg-slate-900 border-slate-800 hover:border-slate-700'
    } group hover:-translate-y-2`}>

      {stock.isAIRecommendation && (
        <div className="absolute top-0 right-0">
          <div className="bg-emerald-500 text-slate-950 text-[10px] font-black px-6 py-1.5 rounded-bl-2xl uppercase tracking-widest shadow-lg z-10 animate-pulse">
            HIGH CONVICTION
          </div>
        </div>
      )}

      <div className="flex justify-between items-start mb-6">
        <div className="flex-1 min-w-0 pr-4">
          <div className="flex flex-col gap-1">
            <h3 className="text-3xl font-black text-white group-hover:text-emerald-400 transition-colors flex items-center gap-3">
              {stock.symbol}
              <span className="text-[10px] px-2 py-0.5 bg-slate-800 border border-slate-700 rounded-lg text-emerald-400 font-black tracking-widest uppercase">
                {stock.marketCap}
              </span>
            </h3>
            <p className="text-slate-500 text-xs font-black truncate uppercase tracking-tighter">{stock.name}</p>
          </div>
        </div>
        <button 
          onClick={() => onToggleSave(stock.symbol)}
          className={`p-3 rounded-2xl transition-all ${isSaved ? 'text-yellow-400 bg-yellow-400/10 shadow-inner ring-1 ring-yellow-400/30' : 'text-slate-600 hover:text-white bg-slate-800'}`}
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill={isSaved ? "currentColor" : "none"} viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11.049 2.927c.3-.921 1.603-.921 1.902 0l1.519 4.674a1 1 0 00.95.69h4.915c.969 0 1.371 1.24.588 1.81l-3.976 2.888a1 1 0 00-.363 1.118l1.518 4.674c.3.922-.755 1.688-1.538 1.118l-3.976-2.888a1 1 0 00-1.176 0l-3.976 2.888c-.783.57-1.838-.197-1.538-1.118l1.518-4.674a1 1 0 00-.363-1.118l-3.976-2.888c-.784-.57-.382-1.81.588-1.81h4.914a1 1 0 00.951-.69l1.519-4.674z" />
