    e.preventDefault();
    if (!searchQuery.trim() || searchingTicker) return;

    setSearchingTicker(true);
    const ticker = searchQuery.trim().toUpperCase();

    if (stocks.some(s => s.symbol === ticker)) {
      setSearchQuery('');
      setSearchingTicker(false);
      return;
