            </div>
          </div>

          <div className="flex flex-col sm:flex-row items-center gap-4 w-full md:w-auto">
            <form onSubmit={handleAddTicker} className="relative w-full sm:w-80">
              <input 
                type="text" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search Ticker (e.g. MSTR)..."
                className="w-full bg-slate-950 border border-slate-800 rounded-2xl py-3.5 pr-12 pl-5 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500 transition-all placeholder:text-slate-700 font-bold"
              />
