import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { Stock } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const STOCK_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    symbol: { type: Type.STRING },
    name: { type: Type.STRING },
    price: { type: Type.NUMBER },
    targetPrice: { type: Type.NUMBER },
    upside: { type: Type.NUMBER },
    peRatio: { type: Type.STRING },
    marketCap: { type: Type.STRING },
    rsi: { type: Type.NUMBER },
    vwap: { type: Type.NUMBER },
    vwapUpper: { type: Type.NUMBER },
    vwapLower: { type: Type.NUMBER },
    movingAverage: { type: Type.STRING },
    sector: { type: Type.STRING },
    description: { type: Type.STRING },
    analystSentiment: { type: Type.STRING },
    nextEarningsDate: { type: Type.STRING },
    riskScore: { type: Type.NUMBER },
    rewardScore: { type: Type.NUMBER },
    isAIRecommendation: { type: Type.BOOLEAN },
    recommendationReason: { type: Type.STRING },
    priceHistory: {
      type: Type.ARRAY,
      items: { type: Type.NUMBER }
    }
  },
  required: [
    "symbol", "name", "price", "targetPrice", "upside", "marketCap", 
    "sector", "priceHistory", "nextEarningsDate", "riskScore", 
    "rewardScore", "isAIRecommendation", "recommendationReason",
    "vwap", "vwapUpper", "vwapLower"
  ]
};

export const fetchHighGrowthStocks = async (): Promise<Stock[]> => {
  const prompt = `Act as an expert Wall Street quantitative analyst. Scan the US stock market for 15-20 stocks where the consensus analyst price target reflects at least 100% upside (2x return).

  STRICT AI RECOMMENDATION RULES:
  - 'isAIRecommendation' MUST BE FALSE for almost all stocks.
  - ONLY mark a stock as TRUE if it is a "Perfect Setup": RSI between 30-55 (not overbought), price currently consolidating near the VWAP, and a massive fundamental catalyst (e.g. AI breakthrough, FDA approval, earnings turnaround).
  - You must only have 2 or 3 'true' recommendations in the entire list of 20.
  - Provide a compelling 1-sentence 'recommendationReason' for these picks.

  DATA INTEGRITY RULES:
  - 'marketCap' MUST be accurate and clearly visible (e.g., "12.5B", "850M").
  - 'upside' MUST be a number representing percentage (e.g., 145 for 145%).
  - Include 'nextEarningsDate' (exact or best estimate).
  - 'priceHistory' must be a 10-day realistic closing price sequence.
  - 'vwap' should be the volume weighted average price, with 'vwapUpper' and 'vwapLower' acting as standard deviation bands (+/- 2-4%).`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: STOCK_SCHEMA
        }
      },
    });

    const resultText = response.text;
    if (!resultText) return [];

    let stocks: Stock[] = JSON.parse(resultText);

    // Safety check for upside requirement (Strictly 100%+)
    stocks = stocks.filter(s => s.upside >= 100);

    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    const chunks = (groundingMetadata?.groundingChunks as any[]) || [];
    const sourceUrls = chunks.filter(c => c.web).map(c => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '' }));

    return stocks.map(stock => ({
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    }));
  } catch (error) {
    console.error("Error fetching stocks:", error);
    throw error;
  }
};

export const fetchStockByTicker = async (ticker: string): Promise<Stock | null> => {
  const prompt = `Deep analysis for ${ticker.toUpperCase()}. Evaluate if this is a high-conviction 2X breakout candidate. Include all technical markers (RSI, Triple VWAP, 50-day MA) and financial data (Market Cap, P/E, Upside).`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: STOCK_SCHEMA
      },
    });

    const resultText = response.text;
    if (!resultText) return null;

    const stock: Stock = JSON.parse(resultText);
    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    const chunks = (groundingMetadata?.groundingChunks as any[]) || [];
    const sourceUrls = chunks.filter(c => c.web).map(c => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '' }));

    return {
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    };
  } catch (error) {
    console.error(`Error fetching ${ticker}:`, error);
    return null;
  }
};

import React from 'react';
import { Stock } from '../types';

interface StockCardProps {
  stock: Stock;
  onToggleSave: (symbol: string) => void;
  isSaved: boolean;
}

export const StockCard: React.FC<StockCardProps> = ({ stock, onToggleSave, isSaved }) => {
  const generateSparkline = (data: number[]) => {
    if (!data || data.length < 2) return null;
    const min = Math.min(...data, stock.vwapLower || stock.vwap * 0.95);
    const max = Math.max(...data, stock.vwapUpper || stock.vwap * 1.05);
    const range = max - min || 1;
    const width = 200;
    const height = 60;

    const points = data.map((val, i) => {
      const x = (i / (data.length - 1)) * width;
      const y = height - ((val - min) / range) * height;
      return `${x},${y}`;
    }).join(' ');

    const vwapY = height - ((stock.vwap - min) / range) * height;
    const upperY = height - (((stock.vwapUpper || stock.vwap * 1.02) - min) / range) * height;
    const lowerY = height - (((stock.vwapLower || stock.vwap * 0.98) - min) / range) * height;

    return (
      <svg width="100%" height={height} viewBox={`0 0 ${width} ${height}`} className="overflow-visible preserve-3d">
        <line x1="0" y1={upperY} x2={width} y2={upperY} stroke="#f59e0b" strokeWidth="0.5" strokeDasharray="2" opacity="0.3" />
        <line x1="0" y1={vwapY} x2={width} y2={vwapY} stroke="#f59e0b" strokeWidth="1" strokeDasharray="4" opacity="0.6" />
        <line x1="0" y1={lowerY} x2={width} y2={lowerY} stroke="#f59e0b" strokeWidth="0.5" strokeDasharray="2" opacity="0.3" />
        <polyline
          fill="none"
          stroke={stock.isAIRecommendation ? "#10b981" : "#60a5fa"}
          strokeWidth="3"
          strokeLinecap="round"
          strokeLinejoin="round"
          points={points}
          className="drop-shadow-[0_0_8px_rgba(16,185,129,0.3)]"
        />
      </svg>
    );
  };

  const getScoreColor = (score: number, inverse = false) => {
    if (inverse) {
      if (score >= 7) return 'bg-red-500';
      if (score >= 4) return 'bg-yellow-500';
      return 'bg-green-500';
    } else {
      if (score >= 7) return 'bg-green-500';
      if (score >= 4) return 'bg-blue-500';
      return 'bg-slate-600';
    }
  };

  return (
    <div className={`relative flex flex-col h-full rounded-[2.5rem] p-6 sm:p-8 transition-all duration-500 shadow-2xl border-2 overflow-hidden ${
      stock.isAIRecommendation 
      ? 'bg-slate-900 border-emerald-500/80 shadow-[0_0_40px_rgba(16,185,129,0.15)] ring-1 ring-emerald-500/30' 
