import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import { Stock } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const STOCK_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    symbol: { type: Type.STRING },
    name: { type: Type.STRING },
    price: { type: Type.NUMBER },
    targetPrice: { type: Type.NUMBER },
    upside: { type: Type.NUMBER },
    peRatio: { type: Type.STRING },
    marketCap: { type: Type.STRING },
    rsi: { type: Type.NUMBER },
    vwap: { type: Type.NUMBER },
    vwapUpper: { type: Type.NUMBER },
    vwapLower: { type: Type.NUMBER },
    movingAverage: { type: Type.STRING },
    sector: { type: Type.STRING },
    description: { type: Type.STRING },
    analystSentiment: { type: Type.STRING },
    nextEarningsDate: { type: Type.STRING },
    riskScore: { type: Type.NUMBER },
    rewardScore: { type: Type.NUMBER },
    isAIRecommendation: { type: Type.BOOLEAN },
    recommendationReason: { type: Type.STRING },
    priceHistory: {
      type: Type.ARRAY,
      items: { type: Type.NUMBER }
    }
  },
  required: [
    "symbol", "name", "price", "targetPrice", "upside", "marketCap", 
    "sector", "priceHistory", "nextEarningsDate", "riskScore", 
    "rewardScore", "isAIRecommendation", "recommendationReason",
    "vwap", "vwapUpper", "vwapLower"
  ]
};

export const fetchHighGrowthStocks = async (): Promise<Stock[]> => {
  // Using gemini-3-flash-preview for the batch fetch as it's more resilient to timeouts when using Google Search grounding
  const prompt = `Act as a senior quantitative equity researcher. Scan for US-listed stocks with analyst consensus price targets reflecting a MINIMUM of 100% (2x) upside.

  STRICT SELECTIVITY RULES:
  - Only mark 'isAIRecommendation: true' for the 2-3 absolute best technical setups.
  - Setup must have: RSI < 60, price near VWAP support, and strong business growth.
  - 'marketCap' is MANDATORY (e.g., "12.4B", "500M").
  - DO NOT include stocks with <100% upside.
  - Provide exactly 12 stocks to ensure system stability.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: STOCK_SCHEMA
        },
        temperature: 0.1,
        seed: 42 
      },
    });

    const resultText = response.text;
    if (!resultText) return [];

    let stocks: Stock[] = JSON.parse(resultText);

    // Server-side filter to guarantee 100% floor
    stocks = stocks.filter(s => s.upside >= 100);

    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    const chunks = (groundingMetadata?.groundingChunks as any[]) || [];
    const sourceUrls = chunks.filter(c => c.web).map(c => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '' }));

    return stocks.map(stock => ({
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    }));
  } catch (error) {
    console.error("Error fetching stocks:", error);
    throw error;
  }
};

export const fetchStockByTicker = async (ticker: string): Promise<Stock | null> => {
  const prompt = `Perform institutional analysis on ${ticker.toUpperCase()}. Evaluate 2x upside potential. Include full technical/financial stats and Market Cap.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: STOCK_SCHEMA,
        temperature: 0.1
      },
    });

    const resultText = response.text;
    if (!resultText) return null;

    const stock: Stock = JSON.parse(resultText);
    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    const chunks = (groundingMetadata?.groundingChunks as any[]) || [];
    const sourceUrls = chunks.filter(c => c.web).map(c => ({ title: c.web?.title || 'Source', uri: c.web?.uri || '' }));

    return {
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    };
  } catch (error) {
    console.error(`Error fetching ${ticker}:`, error);
    return null;
  }
};

