  const start = cleaned.indexOf('[');
  const end = cleaned.lastIndexOf(']');
  if (start !== -1 && end !== -1) {
    return cleaned.substring(start, end + 1);
  }
  return cleaned;
};

export const fetchHighGrowthStocks = async (): Promise<Stock[]> => {
  // Reduced to 6 stocks to prevent timeouts (RPC Error Code 6)
  const prompt = `Return a JSON array of 6 US stocks with analyst targets reflecting >100% upside.

  Constraints:
  - Return ONLY the JSON array.
  - upside must be >= 100.
  - mark isAIRecommendation: true for the best setup.
  - Include marketCap (e.g. "1.2B").
  - priceHistory: 10 daily closing prices.`;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: STOCK_SCHEMA
        },
        temperature: 0.1,
      },
    });

    const resultText = cleanJsonResponse(response.text || "[]");
    let stocks: Stock[] = JSON.parse(resultText);

    // Final check for upside
    stocks = stocks.filter(s => s.upside >= 100);

    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    const chunks = (groundingMetadata?.groundingChunks as any[]) || [];
    const sourceUrls = chunks.filter(c => c.web).map(c => ({ 
      title: c.web?.title || 'מקור מידע', 
      uri: c.web?.uri || '' 
    }));

    return stocks.map(stock => ({
      ...stock,
      sourceUrls,
      analystSentiment: (stock.analystSentiment as any) || 'Bullish'
    }));
  } catch (error) {
    console.error("Error fetching stocks:", error);
    throw error;
  }
};

